const body = $('Event Registration Webhook').first().json.body || {};
const data = body.data || {};
const required = ['name', 'phone'];
const missing = required.filter((key) => !String(data[key] || '').trim());
if (missing.length) return [{ json: { ok: false, statusCode: 400, message: '\u7f3a\u5c11\u5fc5\u586b\u6b04\u4f4d\uff1a' + missing.join(', ') } }];
const companions = Number(data.companions || 0);
if (!Number.isFinite(companions) || companions < 0) return [{ json: { ok: false, statusCode: 400, message: '\u540c\u884c\u4eba\u6578\u683c\u5f0f\u932f\u8aa4' } }];
function taipeiParts(date) {
  return Object.fromEntries(new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Taipei',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  }).formatToParts(date).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
}
const parts = taipeiParts(new Date());
return [{ json: {
  ok: true,
  eventId: String(data.eventId || '').trim(),
  eventTitle: data.eventId ? '\u6307\u5b9a\u6d3b\u52d5' : '\u7c3d\u5230\u5165\u53e3',
  community: '',
  name: String(data.name).trim(),
  phone: String(data.phone).trim(),
  companions,
  note: String(data.note || '').trim(),
  noteText: String(data.note || '').trim(),
  lineUserId: String(data.lineUserId || '').trim(),
  lineDisplayName: String(data.lineDisplayName || '').trim(),
  liffLanguage: String(data.liffLanguage || '').trim(),
  liffOS: String(data.liffOS || '').trim(),
  isInClient: Boolean(data.isInClient),
  registrationId: 'SIGN-' + parts.year + parts.month + parts.day + '-' + parts.hour + parts.minute + parts.second,
  status: 'registered'
} }];

const input = $('Validate Payload').first().json;
if (!input.ok) return [{ json: input }];
const registrations = $('Query Existing Registrations').all();
function taipeiDateKey(value) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return '';
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Taipei',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(date).filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  return parts.year + '-' + parts.month + '-' + parts.day;
}
const today = taipeiDateKey();
const todayCompact = today.replaceAll('-', '');
function textFromValue(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return value.map(textFromValue).filter(Boolean).join('');
  if (value.plain_text) return String(value.plain_text);
  if (value.content) return String(value.content);
  if (value.text?.content) return String(value.text.content);
  if (value.name) return String(value.name);
  if (value.title) return textFromValue(value.title);
  if (value.rich_text) return textFromValue(value.rich_text);
  if (value.select) return textFromValue(value.select);
  if (value.date) return value.date.start || '';
  if (value.phone_number) return String(value.phone_number);
  if (value.value) return textFromValue(value.value);
  return '';
}
function prop(json, names) {
  const wanted = Array.isArray(names) ? names : [names];
  for (const name of wanted) {
    if (json[name] != null) return textFromValue(json[name]).trim();
    const p = json.properties?.[name];
    if (p != null) return textFromValue(p).trim();
  }
  return '';
}
function normalizePhone(value) {
  return String(value || '').replace(/[^0-9]/g, '');
}
function createdDateKey(json, registrationId) {
  const systemDate = taipeiDateKey(json.created_time || json.createdTime || json.createdAt);
  if (systemDate) return systemDate;
  const match = String(registrationId || '').match(/SIGN-(\d{4})(\d{2})(\d{2})/);
  return match ? match[1] + '-' + match[2] + '-' + match[3] : '';
}
const inputLineUserId = String(input.lineUserId || '').trim();
const inputPhone = normalizePhone(input.phone);
const duplicate = registrations.find((item) => {
  const json = item.json || {};
  const registrationId = prop(json, ['\u5831\u540d\u7de8\u865f', 'registrationId', 'title']);
  const status = prop(json, ['\u72c0\u614b', 'status']) || 'registered';
  if (status === 'cancelled') return false;
  const createdAt = createdDateKey(json, registrationId);
  if (createdAt !== today && !registrationId.includes('SIGN-' + todayCompact)) return false;
  const lineUserId = prop(json, ['LINE User ID', 'lineUserId']);
  const phone = normalizePhone(prop(json, ['\u96fb\u8a71', 'phone']));
  if (inputLineUserId && lineUserId && lineUserId === inputLineUserId) return true;
  return inputPhone && phone && phone === inputPhone;
});
if (duplicate) {
  return [{ json: { ok: false, statusCode: 409, duplicate: true, message: '\u4eca\u5929\u5df2\u7d93\u5b8c\u6210\u7c3d\u5230\uff0c\u8acb\u52ff\u91cd\u8907\u7c3d\u5230\u3002' } }];
}
return [{ json: { ...input, eventDate: '', duplicate: false } }];
